          "title": "杯量不等于浓度，泡沫也不等于萃取质量",
          "text": "对于同一份咖啡，增加出液量通常会改变饮料浓度和风味平衡；但只看毫升数，无法知道溶出了多少物质。杯中的泡沫也只是外观现象，不能单独证明“与原厂一样”。判断可填充方案，需要在同一机器与杯量下，记录粉量、出液重量、操作条件与感官结果；这样才能区分浓度变化、滤渣问题和密封失败。",
