      "category": "咖啡豆",
      "title": "可填充胶囊为什么会淡、堵或有渣：豆、研磨和流路一起看",
      "desc": "从粉量与出液的关系，到研磨阻力、保存和滤网，理解同一颗填充胶囊为何会出现不同结果。",
